def transform(grid):
    h, w = len(grid), len(grid[0])
    axes = (
        (lambda r, c: r),
        (lambda r, c: c - r),
        (lambda r, c: r + c),
    )
    candidates = []
    for coordinate in axes:
        groups = {}
        for r, row in enumerate(grid):
            for c, color in enumerate(row):
                if color:
                    groups.setdefault(coordinate(r, c), set()).add(color)
        if groups and all(len(colors) == 1 for colors in groups.values()):
            candidates.append((len(groups), groups))
    if not candidates:
        raise ValueError("No consistent stripe direction found")
    period, groups = min(candidates, key=lambda item: item[0])
    mapping = {}
    for offset, colors in groups.items():
        residue = offset % period
        color = next(iter(colors))
        if residue in mapping and mapping[residue] != color:
            raise ValueError("Stripe positions do not define a unique period")
        mapping[residue] = color
    if len(mapping) != period:
        raise ValueError("Stripe period has unobserved residues")
    coordinate = next(coordinate for coordinate in axes if _valid_axis(grid, coordinate, groups))
    return [[mapping[coordinate(r, c) % period] for c in range(w)] for r in range(h)]


def _valid_axis(grid, coordinate, groups):
    found = {}
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color:
                found.setdefault(coordinate(r, c), set()).add(color)
    return found == groups
